import type { VaultData } from "./model";
import { headerOf, type SlotA, type VaultFile, type VaultHeader, type VaultMode } from "./vault";

export type KeySource = "generate" | "import";

export interface SetupNeeds {
    /** A vault password ("stored") or a key file password (generated key in "ram"). */
    password: boolean;
    /** A key generated by the mod exists nowhere else, so its key file must be saved first. */
    keyFile: boolean;
}

export function setupNeeds(source: KeySource, mode: VaultMode): SetupNeeds {
    return { password: mode === "stored" || source === "generate", keyFile: source === "generate" };
}

/** "Nur RAM": no private key material stays in the vault. */
export interface PrivateKeyOptions {
    /** Show the key after confirming the vault password; only "Stored" mode has a password to confirm. */
    show: boolean;
    /** Remove the stored key: switch to "RAM only", unlocking needs the key file from then on. */
    remove: boolean;
    /** Store the key on this PC again: switch to "Stored". */
    store: boolean;
}

/** What the settings page offers for the own private key. */
export function privateKeyOptions(unlocked: boolean, mode: VaultMode | undefined): PrivateKeyOptions {
    const stored = unlocked && mode === "stored";
    return { show: stored, remove: stored, store: unlocked && mode === "ram" };
}

export function withoutPrivateKeys(data: VaultData): VaultData {
    const { privateKey: _ownPrivate, ...self } = data.self;
    return { ...data, self, oldKeys: data.oldKeys.map(({ privateKey: _oldPrivate, ...k }) => k) };
}

export function withPrivateKey(data: VaultData, armoredPrivateKey: string): VaultData {
    return { ...data, self: { ...data.self, privateKey: armoredPrivateKey } };
}

export function headerForMode(file: VaultFile, mode: VaultMode, slotA?: SlotA): VaultHeader {
    const { a: _oldSlot, w: windows, ...rest } = headerOf(file);
    // "RAM only" keeps no private key, so unlocking with Windows would open nothing: slot W goes too.
    if (mode === "ram") return { ...rest, mode };
    if (!slotA) throw new Error("The \"Stored\" mode needs a password.");
    return { ...rest, mode, a: slotA, ...(windows ? { w: windows } : {}) };
}

/** Replaces the header of a vault file; the payload is re-sealed on the next save anyway. */
export function fileWithHeader(file: VaultFile, header: VaultHeader): VaultFile {
    return { ...header, updated: file.updated, iv: file.iv, ct: file.ct };
}

/** Key files come armored (.asc) or binary (.gpg); OpenPGP.js needs to know which. */
export function decodeKeyFile(bytes: Uint8Array): string | Uint8Array {
    const head = new TextDecoder("utf-8", { fatal: false }).decode(bytes.subarray(0, 4096));
    if (!head.includes("-----BEGIN PGP")) return bytes;
    return new TextDecoder("utf-8", { fatal: false }).decode(bytes);
}
